# =============================================================================
# LOAD LOCKED LAYERS (pre-simplified display versions - see prepare_locked_layers.R)
# =============================================================================
.load_locked <- function(path, label) {
  tryCatch({
    lyr <- st_read(path, quiet = TRUE)
    cat(sprintf("✓ Loaded %s: %d features\n", label, nrow(lyr)))
    lyr
  }, error = function(e) {
    cat(sprintf("Warning: could not load %s: %s\n", label, e$message))
    NULL
  })
}

locked_layers <- list(
  pa   = .load_locked("data/spatial/display/protected_areas_display.gpkg",  "Protected Areas"),
  refs = .load_locked("data/spatial/display/refs_facilities_display.gpkg",   "REFS Facilities"),
  agri = .load_locked("data/spatial/display/agriculture_zones_display.gpkg", "Agriculture Zones")
)

